22	/**
23	 * Simple bean representing an invocation event on a Mock.
24	 * @author laurent
25	 */
26	public class MockInvocationEvent extends ApplicationEvent {
27	
28	   /** */
29	   private final String serviceName;
30	   /** */
31	   private final String serviceVersion;
32	   /** */
33	   private final String mockResponse;
34	   /** */
35	   private final Date invocationTimestamp;
36	   /** */
37	   private final long duration;
38	
39	   /**
40	    * Create a new mock invocation event.
41	    * @param source              Source object for event
42	    * @param serviceName         Name of invoked service
43	    * @param serviceVersion      Version of invoked service
44	    * @param mockResponse        Mock response returned during invocation
45	    * @param invocationTimestamp Timestamp of invocation
