101	   @RequestMapping(value = "/mcp/{service}/{version}/sse", method = { RequestMethod.GET })
102	   public SseEmitter handleSSE(@PathVariable("service") String serviceName, @PathVariable("version") String version) {
103	      log.info("Handling a Mcp SSE for service {} and version {}", serviceName, version);
104	
105	      String sessionId = UUID.randomUUID().toString();
106	      log.debug("Creating new SSE connection for session: {}", sessionId);
107	
108	      SseEmitter emitter = new SseEmitter(Duration.ofSeconds(600).toMillis());
109	      emitter.onCompletion(() -> {
110	         log.debug("SSE connection completed for session: {}", sessionId);
111	         channelsBySessionId.remove(sessionId);
112	      });
113	      emitter.onTimeout(() -> {
114	         log.debug("SSE connection timed out for session: {}", sessionId);
115	         channelsBySessionId.remove(sessionId);
116	      });
117	
118	      channelsBySessionId.put(sessionId, new SseTransportChannel(sessionId, emitter));
119	
120	      // If serviceName was encoded with '+' instead of '%20', remove them.
121	      if (serviceName.contains("+")) {
122	         serviceName = serviceName.replace('+', ' ');
123	      }
124	      final String serviceNameFinal = serviceName;
125	      sseMvcExecutor.execute(() -> {
126	         try {
127	            SseEmitter.SseEventBuilder event = SseEmitter.event().name("endpoint").id(sessionId)
128	                  .data("/mcp/" + serviceNameFinal + "/" + version + "/message?sessionId=" + sessionId);
129	            emitter.send(event);
130	         } catch (Exception e) {
131	            log.error("Failed to send initial endpoint event: {}", e.getMessage());
132	            emitter.completeWithError(e);
133	         }
134	      });
135	      return emitter;
136	   }
