194	   private McpSchema.JSONRPCResponse handleMcpRequest(String serviceName, String version,
195	         McpSchema.JSONRPCRequest request, HttpHeaders headers) throws McpError {
196	      // If serviceName was encoded with '+' instead of '%20', remove them.
197	      if (serviceName.contains("+")) {
198	         serviceName = serviceName.replace('+', ' ');
199	      }
200	      // Find matching service.
201	      Service service = serviceRepository.findByNameAndVersion(serviceName, version);
202	      if (service == null) {
203	         log.debug("Service {}:{} not found", serviceName, version);
204	         throw new McpError("Invalid service name or version");
205	      }
206	
207	      Object result = null;
208	      switch (request.method()) {
209	         case McpSchema.METHOD_INITIALIZE -> {
210	            result = handleInitializeRequest(request, service);
211	         }
212	         case McpSchema.METHOD_TOOLS_LIST -> {
213	            result = handleToolsListRequest(request, service);
214	         }
215	         case McpSchema.METHOD_TOOLS_CALL -> {
216	            result = handleToolsCallRequest(request, headers, service);
217	         }
218	      }
219	
220	      McpSchema.JSONRPCResponse response = null;
221	      if (result != null) {
222	         response = new McpSchema.JSONRPCResponse(McpSchema.JSONRPC_VERSION, request.id(), result, null);
223	      } else {
224	         response = new McpSchema.JSONRPCResponse(McpSchema.JSONRPC_VERSION, request.id(), null,
225	               new McpSchema.JSONRPCResponse.JSONRPCError(McpSchema.ErrorCodes.METHOD_NOT_FOUND,
226	                     "Unsupported method: " + request.method(), null));
227	      }
228	
229	      return response;
230	   }
