package io.github.microcks.util.tracing;

import io.github.microcks.event.TraceEvent;
import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.sdk.trace.ReadableSpan;

import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Utility class providing helpers to filter and match spans and trace events against subscription criteria. Filtering
 * relies on simple wildcard patterns where '*' matches anything and any other value is treated as a regular expression
 * (falling back to exact equality when the pattern is not a valid regex).
 */
public final class SpanFilterUtil {

   /** The attribute key holding the service name on a span. */
   private static final AttributeKey<String> SERVICE_NAME = AttributeKey.stringKey("service.name");
   /** The attribute key holding the operation name on a span. */
   private static final AttributeKey<String> OPERATION_NAME = AttributeKey.stringKey("operation.name");
   /** The attribute key holding the client address on a span. */
   private static final AttributeKey<String> CLIENT_ADDRESS = AttributeKey.stringKey("client.address");

   /**
    * Private constructor to prevent instantiation of utility class.
    */
   private SpanFilterUtil() {
      throw new UnsupportedOperationException("Utility class cannot be instantiated");
   }

   /**
    * Match a value against a wildcard pattern.
    *
    * @param pattern The pattern to match against. '*' matches any non-null value, otherwise the pattern is treated as a
    *                full regular expression (falling back to exact equality if invalid).
    * @param value   The value to test.
    * @return true if the value matches the pattern, false otherwise.
    */
   public static boolean matchesWildcard(String pattern, String value) {
      if (pattern == null && value == null) {
         return true;
      }
      if (pattern == null || value == null) {
         return false;
      }
      if ("*".equals(pattern)) {
         return true;
      }
      try {
         return Pattern.matches(pattern, value);
      } catch (PatternSyntaxException e) {
         // Not a valid regex, fall back to exact string equality.
         return pattern.equals(value);
      }
   }

   /**
    * Extract a {@link TraceEvent} from the spans of a given trace. It looks up the 'service.name', 'operation.name' and
    * 'client.address' attributes across the provided spans.
    *
    * @param traceId The identifier of the trace.
    * @param spans   The spans belonging to the trace.
    * @return A TraceEvent carrying the extracted values (null values when the corresponding attribute is absent).
    */
   public static TraceEvent extractTraceEvent(String traceId, List<ReadableSpan> spans) {
      String service = extractAttribute(spans, SERVICE_NAME);
      String operation = extractAttribute(spans, OPERATION_NAME);
      String clientAddress = extractAttribute(spans, CLIENT_ADDRESS);
      return new TraceEvent(traceId, service, operation, clientAddress);
   }

   /**
    * Check whether a trace event matches the provided filter criteria. Each field of the event is matched against its
    * respective pattern using {@link #matchesWildcard(String, String)}.
    *
    * @param event         The trace event to test.
    * @param service       The service name pattern.
    * @param operation     The operation name pattern.
    * @param clientAddress The client address pattern.
    * @return true if all three event fields match their respective patterns, false otherwise.
    */
   public static boolean matchesTraceEvent(TraceEvent event, String service, String operation, String clientAddress) {
      return matchesWildcard(service, event.service()) && matchesWildcard(operation, event.operation())
            && matchesWildcard(clientAddress, event.clientAddress());
   }

   /** Extract the first non-null value of the given attribute key across the provided spans. */
   private static String extractAttribute(List<ReadableSpan> spans, AttributeKey<String> key) {
      if (spans == null) {
         return null;
      }
      for (ReadableSpan span : spans) {
         String value = span.toSpanData().getAttributes().get(key);
         if (value != null) {
            return value;
         }
      }
      return null;
   }
}
