package io.github.microcks.web;

import io.github.microcks.event.TraceEvent;
import io.github.microcks.service.SpanStorageService;
import io.github.microcks.util.tracing.SpanFilterUtil;
import io.opentelemetry.sdk.trace.ReadableSpan;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Manages live subscriptions to trace events. Clients register an {@link SseEmitter} together with filtering criteria
 * and receive Server-Sent Events whenever new matching trace data arrives.
 */
@Component
public class TraceSubscriptionManager {

   private static final Logger log = LoggerFactory.getLogger(TraceSubscriptionManager.class);

   /** The name of the SSE event carrying trace updates. */
   private static final String TRACE_EVENT_NAME = "trace";
   /** The name of the SSE heartbeat event. */
   private static final String HEARTBEAT_EVENT_NAME = "heartbeat";

   private final SpanStorageService spanStorageService;

   /** Registered subscriptions. CopyOnWriteArrayList allows safe iteration while sending events. */
   private final List<Subscription> subscriptions = new CopyOnWriteArrayList<>();

   /**
    * Create a new TraceSubscriptionManager.
    *
    * @param spanStorageService The service used to retrieve spans for a trace
    */
   public TraceSubscriptionManager(SpanStorageService spanStorageService) {
      this.spanStorageService = spanStorageService;
   }

   /**
    * Register an emitter for a filtered live stream of trace events. A heartbeat event is immediately sent to confirm
    * the connection is established.
    *
    * @param emitter       The SSE emitter to register
    * @param serviceName   The service name filter pattern (wildcard/regex, may be null)
    * @param operationName The operation name filter pattern (wildcard/regex, may be null)
    * @param clientAddress The client address filter pattern (wildcard/regex, may be null)
    */
   public void subscribe(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
      Subscription subscription = new Subscription(emitter, serviceName, operationName, clientAddress);
      subscriptions.add(subscription);

      emitter.onCompletion(() -> subscriptions.remove(subscription));
      emitter.onTimeout(() -> subscriptions.remove(subscription));
      emitter.onError(t -> subscriptions.remove(subscription));

      // Immediately send a heartbeat to confirm the subscription is live.
      try {
         emitter.send(SseEmitter.event().name(HEARTBEAT_EVENT_NAME).data("ping"));
      } catch (IOException e) {
         log.debug("Failed to send initial heartbeat, completing emitter: {}", e.getMessage());
         emitter.complete();
         subscriptions.remove(subscription);
      }
   }

   /**
    * Handle a trace update by forwarding matching trace data to interested subscribers.
    *
    * @param event The trace event describing which trace was updated
    */
   @EventListener
   public void onTraceUpdated(TraceEvent event) {
      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(event.traceId());
      if (spans.isEmpty()) {
         // No spans stored yet for this trace, nothing to send.
         return;
      }

      // Build an enriched event (including client address) from the stored spans.
      TraceEvent enrichedEvent = SpanFilterUtil.extractTraceEvent(event.traceId(), spans);

      for (Subscription subscription : subscriptions) {
         if (SpanFilterUtil.matchesTraceEvent(enrichedEvent, subscription.serviceName(), subscription.operationName(),
               subscription.clientAddress())) {
            try {
               subscription.emitter().send(SseEmitter.event().name(TRACE_EVENT_NAME).data(enrichedEvent));
            } catch (IOException e) {
               log.debug("Failed to send trace event, completing emitter: {}", e.getMessage());
               subscription.emitter().complete();
               subscriptions.remove(subscription);
            }
         }
      }
   }

   /**
    * Send a heartbeat SSE event to all registered emitters. Emitters that fail to receive the heartbeat are completed
    * and removed.
    */
   public void sendHeartbeats() {
      for (Subscription subscription : subscriptions) {
         try {
            subscription.emitter().send(SseEmitter.event().name(HEARTBEAT_EVENT_NAME).data("ping"));
         } catch (IOException e) {
            log.debug("Failed to send heartbeat, completing emitter: {}", e.getMessage());
            subscription.emitter().complete();
            subscriptions.remove(subscription);
         }
      }
   }

   /** Internal record holding an emitter together with its filter criteria. */
   record Subscription(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
   }
}
